// Package sqlite3 provides the low-level pure-Go client generated by
// hqq-bindgen from sqlite3.idl and the accompanying C11 SQLite server in
// server/. See README.md for the architecture, exposed IDL surface, and C hook
// design.
//
// Regenerate the client and the server glue after changing sqlite3.idl:
//
//	go generate ./sqlite3/...
//
// TestGeneratedFilesAreFresh runs the same command with -check.
package sqlite3

//go:generate go run gosuda.org/hqq/cmd/hqq-bindgen -go-out . -c-out server sqlite3.idl
